import numpy as np

def feature(placements, boards, gains, board, pieces, ids, score, pieces_left, garbage_in, colours):
    """Height of the tallest column after the move, relative to the well height (lower is better)."""
    H, W = boards.shape[1], boards.shape[2]
    filled = boards != 0
    heights = np.zeros(filled.shape[0], dtype=float)
    for r in range(H):
        heights += filled[:, r, :].any(axis=1)
    return -(heights / float(H))

