import math

def feature(placements, boards, gains, board, pieces, ids, score, pieces_left, garbage_in, colours):
    """Per candidate: number of single-colour 2x2 blocks (over all colours) that would be completed on the resulting board, i.e. how many 2x2 all-same-colour squares exist, divided by H*W."""
    k, H, W = boards.shape
    b = boards
    if colours < 1:
        return np.zeros(k, dtype=np.float64)
    total = np.zeros(k, dtype=np.float64)
    # count 2x2 blocks of each colour, one colour at a time (few colours, vectorised over candidates)
    for c in range(1, int(colours) + 1):
        m = (b == c)
        if not m.any():
            continue
        a = m[:, :-1, :-1] & m[:, :-1, 1:] & m[:, 1:, :-1] & m[:, 1:, 1:]
        total += a.sum(axis=(1, 2)).astype(np.float64)
    return total / float(H * W)

import numpy as np

def feature(placements, boards, gains, board, pieces, ids, score, pieces_left, garbage_in, colours):
    """gains/(gains+5) when pieces_left <= 10, else 0 for every candidate."""
    g = gains.astype(float)
    vals = g / (g + 5.0)
    return np.where(pieces_left <= 10, vals, 0.0)

import numpy as np

def feature(placements, boards, gains, board, pieces, ids, score, pieces_left, garbage_in, colours):
    """Logistic ramp r = 1/(1+exp((pieces_left-6)/4)) times gains/(gains+5), per candidate."""
    r = 1.0 / (1.0 + np.exp((float(pieces_left) - 6.0) / 4.0))
    g = np.asarray(gains, dtype=float)
    return r * (g / (g + 5.0))
